package com.logatron.processor.consume;
import com.fasterxml.jackson.databind.ObjectMapper;import com.logatron.contracts.ingestion.*;import com.logatron.processor.configuration.IngestionProperties;import com.logatron.processor.observability.ProcessorMetrics;import com.logatron.processor.store.ClickHouseStore;import org.apache.kafka.clients.consumer.ConsumerRecord;import org.slf4j.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.support.Acknowledgment;import org.springframework.stereotype.Component;import java.time.Duration;import java.util.*;
@Component public class RawLogBatchListener {private static final Logger log=LoggerFactory.getLogger(RawLogBatchListener.class);private final ProcessorPipeline pipeline;private final ClickHouseStore store;private final KafkaTemplate<String,String> kafka;private final ObjectMapper json;private final IngestionProperties p;private final ProcessorMetrics metrics;public RawLogBatchListener(ProcessorPipeline pipeline,ClickHouseStore store,KafkaTemplate<String,String> kafka,ObjectMapper json,IngestionProperties p,ProcessorMetrics metrics){this.pipeline=pipeline;this.store=store;this.kafka=kafka;this.json=json;this.p=p;this.metrics=metrics;}@KafkaListener(topics="${logatron.kafka.raw}",containerFactory="batchKafkaListenerContainerFactory")public void consume(List<ConsumerRecord<String,String>> records,Acknowledgment ack)throws Exception{metrics.received.increment(records.size());List<CanonicalLogEvent> events=new ArrayList<>();List<DeadLetterEvent> failures=new ArrayList<>();for(ConsumerRecord<String,String> record:records){ProcessingOutcome o=pipeline.process(record.value());if(o.event()!=null){events.add(o.event());metrics.parsed.increment();metrics.normalized.increment();metrics.masked.increment();if(o.duplicate())metrics.duplicates.increment();log.atDebug().addKeyValue("topic",record.topic()).addKeyValue("partition",record.partition()).addKeyValue("offset",record.offset()).addKeyValue("eventId",o.event().eventId()).addKeyValue("stage","canonical").log("log event processed");}else{failures.add(o.deadLetter());metrics.rejected.increment();}}store.store(events);for(CanonicalLogEvent e:events){String key=e.projectId()+":"+e.serviceId();String body=json.writeValueAsString(e);send(p.kafka().enriched(),key,body);if("WARN".equals(e.level())||"ERROR".equals(e.level())||"FATAL".equals(e.level()))send(p.kafka().errors(),key,body);}for(DeadLetterEvent d:failures){send(p.kafka().dlq(),d.projectId()==null?"unknown":d.projectId().toString(),json.writeValueAsString(d));metrics.dlq.increment();log.atWarn().addKeyValue("eventId",d.eventId()).addKeyValue("stage",d.failureStage()).addKeyValue("failureCode",d.failureCode()).log("log event sent to DLQ");}ack.acknowledge();}private void send(String topic,String key,String value)throws Exception{kafka.send(topic,key,value).get(Duration.ofSeconds(10).toMillis(),java.util.concurrent.TimeUnit.MILLISECONDS);}}